import itertools
cands={'1':np.ones_like(t),'t':t,'sin t':np.sin(t),'cos t':np.cos(t),'x':x,'v':v,'x2':x**2,'x3':x**3,'v2':v**2,'v3':v**3,'xv':x*v,'1/x':1/x,'1/x2':1/x**2,'v/x':v/x,'t*x':t*x,'t*v':t*v,'x*v2':x*v**2,'|v|v':np.abs(v)*v,'sgn v':np.sign(v),'sin2t':np.sin(2*t),'cos2t':np.cos(2*t),'sqrt x':np.sqrt(x),'exp -x':np.exp(-x),'1/v':1/v,'v/x2':v/x**2}
keys=list(cands)
best=[]
for k in range(1,5):
    for combo in itertools.combinations(keys,k):
        A=np.column_stack([cands[c] for c in combo])
        c,res,rk,_=np.linalg.lstsq(A,dv_dt,rcond=None)
        r=dv_dt-A@c
        nmse=np.mean(r**2)/np.var(dv_dt)
        best.append((nmse,combo,np.round(c,4)))
best.sort(key=lambda z:z[0])
for b in best[:12]: print(b)
